// Frozen reference renderer from 4b392f8 (ver.89), for structural parity only.
 function render(){map.classList.toggle('tutorial-frontier',BoukenTutorial.highlightWorld(save));renderWorldParty();map.replaceChildren();actions.replaceChildren();map.style.gridTemplateColumns='repeat('+w.width+',var(--tile-size))';const progress=BoukenProgress.status(w);info.textContent=w.width+'×'+w.height+' ／ 開拓 '+progress.opened+'/'+progress.total+'（'+progress.percent+'%） ／ 施設 '+progress.completedFacilities+'/'+progress.facilities;document.getElementById('progressFill').style.width=progress.percent+'%';document.querySelector('.progress').setAttribute('aria-valuenow',progress.percent);const notice=document.getElementById('clearNotice');notice.hidden=!progress.allExplored;if(progress.allExplored){document.getElementById('clearTitle').textContent=progress.complete?'完全クリア！':'全域開拓達成！';document.getElementById('clearText').textContent=progress.complete?'すべてのマスと施設を攻略しました。':'すべてのマスを開拓しました。すべての施設を訪問すると完全クリアになります。';}
 const treasure=new Set(BoukenBuffs.detected(w,'collection')),people=new Set(BoukenBuffs.detected(w,'companion')),guide=BoukenBuffs.guide(w);const sense=BoukenBuffs.eventSense(w);const senseBox=document.getElementById('eventSense');senseBox.hidden=!sense;if(sense){document.getElementById('senseTitle').textContent='探知 Lv'+sense.level+' · '+sense.count+'か所';const grid=document.getElementById('senseGrid');grid.replaceChildren();grid.style.gridTemplateColumns='repeat('+sense.divisions+',minmax(0,1fr))';grid.style.gridTemplateRows='repeat('+sense.divisions+',minmax(0,1fr))';sense.parts.forEach((count,i)=>{const cell=document.createElement('div');cell.className='sense-cell'+(count?' has-event':'');cell.textContent='';cell.classList.toggle('event-many',count>=2);cell.classList.toggle('event-heavy',count>=4);cell.title=count+'か所';cell.setAttribute('aria-label',(Math.floor(i/sense.divisions)+1)+'行'+(i%sense.divisions+1)+'列：'+count+'か所');grid.append(cell);});}w.terrain.forEach((tid,i)=>{const state=BoukenExplore.visible(w,i),frontier=BoukenExplore.canExplore(w,i),facility=w.facility[i];const cell=document.createElement('button');cell.type='button';cell.className='cell '+state+(frontier?' frontier':'')+(i===playerIndex()?' player':'');cell.style.background=colors[tid]||'#ddd';if(state!=='hidden')BoukenTileImages.draw(cell,tid,facility,facility?ficons[facility]:icons[tid]);cell.setAttribute('aria-label',state==='hidden'&&!frontier?'未発見のマス':`${i%w.width+1}列${Math.floor(i/w.width)+1}行 ${state==='explored'?'開拓済み':state==='revealed'?'透視済み':'開拓可能'}`);if(facility&&state!=='hidden'&&!w.visitedFacilities[i]){const mark=document.createElement('span');mark.className='mark';mark.textContent='!';cell.append(mark);}if(treasure.has(i)||people.has(i)){const spark=document.createElement('span');spark.className='detect '+(treasure.has(i)?'collection':'companion');spark.textContent='✦';spark.setAttribute('aria-label',treasure.has(i)?'宝の気配':'人の気配');cell.append(spark);}if(guide&&guide.origin===i){const arrow=document.createElement('span');arrow.className='guide-arrow';arrow.textContent=guide.arrow;cell.append(arrow);}if(i===playerIndex()){cell.append(playerPortrait());cell.setAttribute('aria-label',cell.getAttribute('aria-label')+' 現在地');}cell.addEventListener('click',()=>tap(i));map.append(cell);});renderRobotRoute();requestAnimationFrame(positionSense);}